"""Artifacts repository protocol and data transfer objects."""
from __future__ import annotations

from dataclasses import dataclass
from datetime import datetime
from typing import Protocol, runtime_checkable
from uuid import UUID


@dataclass(frozen=True)
class ArtifactDTO:
    """Represents a registered file artifact generated by an agent run."""
    id: UUID
    run_id: UUID
    kind: str  # document, diff, log, export
    path: str
    size_bytes: int
    preview: str | None
    created_at: datetime


@dataclass(frozen=True)
class ArtifactCreateDTO:
    """Payload for registering a newly generated artifact."""
    run_id: UUID
    kind: str
    path: str
    size_bytes: int
    preview: str | None = None


@runtime_checkable
class ArtifactsRepository(Protocol):
    """Protocol contract for artifact tracking and metadata retrieval."""

    async def get_artifact_by_id(self, artifact_id: UUID) -> ArtifactDTO | None:
        """
        Retrieve artifact metadata by primary key.

        Args:
            artifact_id: UUID of the artifact.

        Returns:
            ArtifactDTO if found, None otherwise.
        """
        ...

    async def list_artifacts_by_run(self, run_id: UUID) -> list[ArtifactDTO]:
        """
        List all artifacts associated with a specific agent run.

        Args:
            run_id: UUID of the run.

        Returns:
            List of ArtifactDTOs.
        """
        ...

    async def save_artifact(self, data: ArtifactCreateDTO) -> ArtifactDTO:
        """
        Register a newly created artifact record.

        Args:
            data: Artifact creation DTO.

        Returns:
            The created ArtifactDTO.
        """
        ...

    async def delete_artifact(self, artifact_id: UUID) -> bool:
        """
        Delete an artifact metadata record.

        Args:
            artifact_id: UUID of the artifact to delete.

        Returns:
            True if deleted, False if not found.
        """
        ...
